//! Raw values use the existing real immutable native source/storage ledger.
use super::*;
fn fixture()->(Document,Forms,Page,u32){let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);assert_eq!(page.console_eval(&mut doc,&mut forms,r#"var owner=new Document(),node=owner.createElementNS('urn:element','e:Root');node.setAttributeNS('urn:attr','p:Name','old\ud800');var held=node.getAttributeNodeNS('urn:attr','Name'),clone=node.cloneNode(false);node.setAttribute('id','id\udfff');"#).errors,0,"{}",page.report());let Value::Host(node)=page.runtime.execute("node",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("node")};(doc,forms,page,node)}
#[test]
fn inert_attribute_units_snapshot_payload_backing_refusal_and_recovery_are_exact(){
 let(mut doc,mut forms,mut page,node)=fixture();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.generated.len(),b.state.attributes.len(),b.state.dom_commits);let index=b.state.attached_attributes.clone();let(limit,copies)=(b.state.retained_limit,b.state.copy_work);let args=[Value::String("urn:attr".into()),Value::String("q:Name".into()),Value::StringUnits(vec![0xdfff,0x41,0xd800])];
 for storage in [true,false]{if storage{b.state.retained_limit=before.0;}else{b.state.copy_work=0;}assert!(b.set_attribute_ns(node,&args).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.generated.len(),b.state.attributes.len(),b.state.dom_commits),before);assert_eq!(b.state.attached_attributes,index);assert!(b.inert_element_attributes(node).unwrap()[0].value.code_units().eq("old".encode_utf16().chain([0xd800])));b.state.retained_limit=limit;b.state.copy_work=copies;}
 b.set_attribute_ns(node,&args).unwrap();let snapshot=&b.state.inert_documents.generated[before.2].node;let NodeKind::Element{tag,href,attrs,..}=&snapshot.kind else{panic!("source")};assert!(attrs[0].value.code_units().eq([0xdfff,0x41,0xd800]));assert_eq!(attrs[0].name.qualified,"p:Name");let payload=node_bytes(snapshot)+tag.capacity()+href.as_ref().map_or(0,String::capacity)+size_of::<Node>()+2*size_of::<usize>();assert_eq!(b.state.retained,before.0+payload+b.state.inert_documents.backing_bytes()-before.1);assert_eq!(b.state.attributes.len(),before.3);assert_eq!(b.state.attached_attributes,index);drop(b);assert_eq!(page.console_eval(&mut doc,&mut forms,r#"if(node.getAttributeNodeNS('urn:attr','Name')!==held||held.value!=='\udfffA\ud800'||clone.getAttributeNS('urn:attr','Name')!=='old\ud800')throw 'actual recovered source and snapshot';"#).errors,0,"{}",page.report());
}
#[test]
fn inert_attribute_units_id_result_copy_refusal_is_read_only_and_recovers(){
 let(mut doc,mut forms,mut page,node)=fixture();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};assert!(matches!(b.inert_get(node,"id").unwrap(),Value::StringUnits(_)));let before=(b.state.retained,b.state.dom_commits,b.state.inert_documents.generated.len());let(copies,limit)=(b.state.copy_work,b.state.limits.host.string_bytes);
 for copy in [true,false]{if copy{b.state.copy_work=0;}else{b.state.limits.host.string_bytes=1;}assert!(b.inert_get(node,"id").is_err());assert_eq!((b.state.retained,b.state.dom_commits,b.state.inert_documents.generated.len()),before);b.state.copy_work=copies;b.state.limits.host.string_bytes=limit;}
 let Value::StringUnits(value)=b.inert_get(node,"id").unwrap()else{panic!("raw id")};assert_eq!(value,vec![0x69,0x64,0xdfff]);assert_eq!((b.state.retained,b.state.dom_commits,b.state.inert_documents.generated.len()),before);
}
